// Normalizes the raw publications feed into a consistent shape and drops
// anything already seen in a prior cycle. Seen IDs are tracked in GLOBAL
// workflow static data so they're shared with JS - Update Seen Publications
// Store further downstream.
const cfg = $('Set - Config').first().json;
const response = $input.first().json;
const rawPublications = response.publications || response.items || response.results || [];

function normalize(p) {
  return {
    publicationId: p.id || p.publicationId || p.documentId || '',
    title: p.title || p.name || '',
    sourceAgency: p.agency || p.source || cfg.defaultAgency || '',
    publishedAt: p.publishedAt || p.date || p.published_date || null,
    url: p.url || p.link || '',
    summarySnippet: p.summary || p.excerpt || '',
    therapeuticAreaTags: p.therapeuticAreas || p.tags || [],
    productTags: p.products || p.relatedProducts || []
  };
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenPublicationIds) staticData.seenPublicationIds = [];
const seenSet = new Set(staticData.seenPublicationIds);

const normalized = rawPublications.map(normalize);
const newPublications = normalized.filter(p => p.publicationId && !seenSet.has(p.publicationId));

return [{
  json: {
    ...cfg,
    normalizedPublications: newPublications,
    hasNew: newPublications.length > 0,
    scanTimestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;
const monitoredAreas = (item.monitoredTherapeuticAreas || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const monitoredProducts = (item.monitoredProducts || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

function isRelevant(pub) {
  const areaTags = (pub.therapeuticAreaTags || []).map(t => String(t).toLowerCase());
  const productTags = (pub.productTags || []).map(t => String(t).toLowerCase());
  const areaMatch = monitoredAreas.length === 0 || areaTags.some(t => monitoredAreas.includes(t));
  const productMatch = monitoredProducts.length === 0 || productTags.some(t => monitoredProducts.includes(t));
  return areaMatch || productMatch;
}

const relevantPublications = (item.normalizedPublications || []).filter(isRelevant);

return [{
  json: {
    ...item,
    relevantPublications,
    hasRelevant: relevantPublications.length > 0
  }
}];

// Splits the relevant-publications list into one item per publication so
// each gets its own full-text fetch and AI classification.
const item = $input.first().json;
const { relevantPublications, normalizedPublications, ...rest } = item;

return relevantPublications.map(pub => ({
  json: {
    ...rest,
    ...pub
  }
}));

