const upstream = $('JS - Fan Out Relevant Publications').item.json;
const response = $input.first().json;

let parsed = {
  affectedTherapeuticAreas: upstream.therapeuticAreaTags || [],
  affectedProducts: upstream.productTags || [],
  implicationsSummary: '',
  urgency: 'Urgent',
  urgencyReasoning: 'AI classification unavailable this cycle; routed to urgent review as a safety default.',
  complianceActions: []
};
try {
  const raw = String(response.output || response.text || response.response || '{}').replace(/```json|```/g, '').trim();
  const result = JSON.parse(raw);
  parsed = { ...parsed, ...result };
} catch (e) {
  // keep safe default above
}

return [{
  json: {
    ...upstream,
    affectedTherapeuticAreas: parsed.affectedTherapeuticAreas,
    affectedProducts: parsed.affectedProducts,
    implicationsSummary: parsed.implicationsSummary,
    urgency: parsed.urgency,
    urgencyReasoning: parsed.urgencyReasoning,
    complianceActions: parsed.complianceActions
  }
}];

