// Records this publication's ID as seen (GLOBAL workflow static data,
// shared with JS - Normalize & Deduplicate Publications) so next cycle
// only looks at what's truly new.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenPublicationIds) staticData.seenPublicationIds = [];

if (item.publicationId && !staticData.seenPublicationIds.includes(item.publicationId)) {
  staticData.seenPublicationIds.push(item.publicationId);
}
if (staticData.seenPublicationIds.length > 2000) {
  staticData.seenPublicationIds = staticData.seenPublicationIds.slice(-2000);
}

return [{ json: { ...item, markedSeen: true } }];
